-- =============================================================================
-- seed_tamil_nadu.sql — Tamil Nadu Manufacturer Research Database → manufacturer organizations
-- =============================================================================
-- Source package : Tamil_Nadu_Manufacturer_Import_Package.zip / Tamil_Nadu_Manufacturer_Database.xlsx
--                  ("TN Database" / tn_manufacturers.* — research cutoff 2026-10-10)
-- Same research IDs and source_ref key as the India seed (india_mfr_research:<ID>): every TN ID also
-- exists in the India package, so running this and seed_part1/2.sql in any order never duplicates.
-- Source rows    : 3236 principal-list records
-- Staged here    : 3220 records (16 identical in-file duplicates folded; see report)
-- Not staged     : 69 "Supplier / service lead" records (not manufacturers; also excluded by the India seed)
--
-- What this script does
--   * Inserts NEW rows only into: organizations, organization_profiles, facilities (one draft, private
--     headquarters row per company with a published location - same convention as
--     app/import_manufacturers.py), admin_internal_notes (provenance + caveats), one import_batches row
--     and one 'imported' onboarding-history event per company. Reuses countries / regions /
--     taxonomy_terms lookups; adds country 'IN' only if it is missing.
--   * Never UPDATEs or DELETEs existing rows. Never creates users, memberships, ownership, onboarding
--     approval, capabilities, certifications or published listings.
--   * Imported organizations are REAL DATA: record_type='REAL' (explicit), organization_type=
--     'manufacturer', entry_source='IMPORTED', onboarding_source='database_import' + import_batch_id,
--     status='claim_pending', verification_status='unverified', no owner / creator / assigned admin,
--     source_ref='india_mfr_research:<research ID>'. Not approved, not visible to Visionaries until an
--     admin approves them and their profile is 100% complete.
--   * Duplicates (section 5): the stable research id (re-runs), then the project's own import rules
--     (app/import_manufacturers.py): same registration id; same name + website; same name + country +
--     city; a bare name match with nothing else to compare is skipped as ambiguous.
--   * DEMO protection: a record that matches an existing DEMO (or TEST) company is NOT imported and the
--     demo record is NOT changed; it is listed as a CONFLICT for an admin to resolve (switch the demo
--     record to Real in the admin portal, or archive it and re-run this file).
--   * Idempotent: re-running inserts nothing new and overwrites nothing.
--   * Single transaction; assertions in section 7 abort and roll back everything on any mismatch.
--
-- Run:  python run_seed.py seed_tamil_nadu.sql   (or psql -v ON_ERROR_STOP=1 -f seed_tamil_nadu.sql)
-- (Too large for browser SQL editors — use psql.)
-- =============================================================================

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

BEGIN;

SET LOCAL lock_timeout = '15s';
SET LOCAL statement_timeout = 0;

-- ---------------------------------------------------------------------------
-- 1. PREFLIGHT — confirm the target schema matches what this script expects
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_missing text;
BEGIN
  SELECT string_agg(t.tbl || '.' || t.col, ', ')
    INTO v_missing
    FROM (VALUES
      ('organizations','id'),('organizations','display_name'),('organizations','organization_type'),
      ('organizations','industry_id'),('organizations','description'),('organizations','website_domain'),
      ('organizations','primary_geography'),('organizations','status'),('organizations','verification_status'),
      ('organizations','source_ref'),('organizations','record_type'),('organizations','entry_source'),
      ('organizations','created_by_user_id'),('organizations','assigned_admin_user_id'),
      ('organizations','onboarding_source'),('organizations','import_batch_id'),('organizations','is_archived'),
      ('import_batches','content_sha256'),('manufacturer_submission_events','idempotency_key'),
      ('manufacturer_submission_events','organization_id'),('manufacturer_submission_events','import_batch_id'),
      ('manufacturer_onboarding','status'),('manufacturer_submissions','kind'),
      ('organization_profiles','organization_id'),('organization_profiles','registration_id'),
      ('organization_profiles','contact_email'),('organization_profiles','contact_phone'),
      ('organization_profiles','address_line1'),('organization_profiles','country_code'),
      ('organization_profiles','region_code'),('organization_profiles','postal_code'),
      ('organization_profiles','company_category'),('organization_profiles','country_name'),
      ('facilities','organization_id'),('facilities','name'),('facilities','address'),
      ('facilities','address_line1'),('facilities','city'),('facilities','state_province'),
      ('facilities','postal_code'),('facilities','country_code'),('facilities','region_code'),
      ('facilities','country_name'),('facilities','visibility'),('facilities','status'),
      ('facilities','is_headquarters'),('facilities','facility_type'),
      ('admin_internal_notes','manufacturer_id'),('admin_internal_notes','note'),
      ('admin_internal_notes','shared_with_manufacturer'),
      ('countries','code'),('countries','name'),('regions','country_code'),('regions','code'),('regions','name'),
      ('taxonomy_terms','id'),('taxonomy_terms','term_type'),('taxonomy_terms','term'),('taxonomy_terms','status'),
      ('memberships','organization_id')
    ) AS t(tbl, col)
   WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns c
                      WHERE c.table_schema = 'public' AND c.table_name = t.tbl AND c.column_name = t.col);
  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'seed.sql preflight: target schema is missing columns: %', v_missing;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conrelid = 'public.organizations'::regclass AND contype = 'c'
                    AND pg_get_constraintdef(oid) LIKE '%entry_source%'
                    AND pg_get_constraintdef(oid) LIKE '%IMPORTED%') THEN
    RAISE EXCEPTION 'seed.sql preflight: organizations.entry_source does not accept ''IMPORTED''';
  END IF;
END $$;

-- Serialize against concurrent writes / a second copy of this script while duplicates are checked.
-- Existing rows stay readable; app writes to organizations wait until COMMIT (typically seconds).
LOCK TABLE public.organizations IN SHARE ROW EXCLUSIVE MODE;
-- Same lock as the CSV importer and Admin Entry: never two imports at once.
SELECT pg_advisory_xact_lock(hashtextextended('xy-import-manufacturers', 0));

-- ---------------------------------------------------------------------------
-- 2. LOOKUPS — reuse existing; add country 'IN' only if absent
-- ---------------------------------------------------------------------------
INSERT INTO public.countries (code, name)
SELECT 'IN', 'India'
 WHERE NOT EXISTS (SELECT 1 FROM public.countries WHERE code = 'IN');

CREATE TEMP TABLE seed_mfr_stage (
  source_ref          text PRIMARY KEY,
  company_id          text NOT NULL UNIQUE,
  display_name        text NOT NULL,
  sector              text,
  company_category    text,
  description         text,
  website_domain      text,
  primary_geography   text,
  contact_email       text,
  contact_phone       text,
  address_line1       text,
  city                text,
  state_name          text,
  country_name        text,
  postal_code         text,
  registration_id     text,
  manufacturer_status text,
  is_factory          boolean NOT NULL DEFAULT false,
  internal_note       text NOT NULL,
  -- resolved during the run
  new_org_id          uuid NOT NULL DEFAULT gen_random_uuid(),
  country_code        text,
  region_code         text,
  industry_id         uuid,
  skip_reason         text,
  existing_org_id     uuid
) ON COMMIT DROP;

-- ---------------------------------------------------------------------------
-- 3. STAGE 3220 cleaned source records (from 3236 principal-list rows)
-- ---------------------------------------------------------------------------
INSERT INTO seed_mfr_stage (source_ref, company_id, display_name, sector, company_category, description, website_domain, primary_geography, contact_email, contact_phone, address_line1, city, state_name, country_name, postal_code, registration_id, manufacturer_status, is_factory, internal_note) VALUES
