-- ---------------------------------------------------------------------------
-- 4. RESOLVE LOOKUPS (existing rows only — nothing created here)
-- ---------------------------------------------------------------------------
UPDATE seed_mfr_stage s
   SET country_code = c.code
  FROM public.countries c
 WHERE c.code = 'IN' AND s.country_name = 'India';

-- State → regions.code, by exact (case-insensitive) name for country IN. No match → NULL.
UPDATE seed_mfr_stage s
   SET region_code = r.code
  FROM (SELECT DISTINCT ON (lower(btrim(name))) lower(btrim(name)) AS lname, code
          FROM public.regions WHERE country_code = 'IN'
         ORDER BY lower(btrim(name)), code) r
 WHERE s.country_code IS NOT NULL AND s.state_name IS NOT NULL
   AND r.lname = lower(s.state_name);

-- Sector → active industry taxonomy term (exact term first, then synonym). No match → NULL.
UPDATE seed_mfr_stage s
   SET industry_id = (
        SELECT tt.id
          FROM public.taxonomy_terms tt
         WHERE tt.term_type = 'industry' AND tt.status = 'active'
           AND (lower(btrim(tt.term)) = lower(s.sector)
                OR lower(s.sector) IN (SELECT lower(btrim(x)) FROM unnest(tt.synonyms::text[]) AS x))
         ORDER BY (lower(btrim(tt.term)) = lower(s.sector)) DESC, tt.created_at, tt.id
         LIMIT 1)
 WHERE s.sector IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 5. DUPLICATES AND DEMO CONFLICTS (first matching rule wins; matched rows are skipped, never merged,
--    and the existing record is never changed)
-- ---------------------------------------------------------------------------
ALTER TABLE seed_mfr_stage ADD COLUMN norm_name text, ADD COLUMN existing_record_type text;
UPDATE seed_mfr_stage SET norm_name = lower(regexp_replace(btrim(display_name), '\s+', ' ', 'g'));

-- Known companies = app.repositories.manufacturer.DEDUP_COMPANY_SQL (keep in sync): every listed
-- manufacturer, REAL and DEMO alike, except TEST, archived records and unapproved per-user placeholders.
CREATE TEMP TABLE seed_existing ON COMMIT DROP AS
SELECT o.id, o.record_type, o.source_ref,
       lower(regexp_replace(btrim(o.display_name), '\s+', ' ', 'g'))                    AS norm,
       lower(replace(btrim(COALESCE(op.registration_id, '')), ' ', ''))                AS reg,
       regexp_replace(split_part(regexp_replace(lower(btrim(COALESCE(o.website_domain, ''))), '^[a-z]+://', ''),
                                 '/', 1), '^www[0-9]?\.', '')                           AS web,
       lower(btrim(COALESCE(op.country_name, f.country_name, '')))                     AS country,
       lower(btrim(COALESCE(f.city, '')))                                              AS city
FROM public.organizations o
LEFT JOIN public.organization_profiles op ON op.organization_id = o.id
LEFT JOIN LATERAL (SELECT city, country_name FROM public.facilities
                   WHERE organization_id = o.id AND is_headquarters AND status <> 'suspended' LIMIT 1) f ON true
WHERE o.organization_type = 'manufacturer'
  AND o.status IN ('active', 'claim_pending')
  AND NOT o.is_archived
  AND o.record_type <> 'TEST'
  AND NOT (o.created_by_user_id IS NOT NULL
           AND o.entry_source = 'MANUFACTURER'
           AND NOT EXISTS (SELECT 1 FROM public.manufacturer_onboarding mo
                           WHERE mo.organization_id = o.id
                             AND (mo.status = 'approved'
                                  OR (mo.personal_information_completed
                                      AND NOT EXISTS (SELECT 1 FROM public.manufacturer_submissions sub
                                                      WHERE sub.organization_id = o.id
                                                        AND sub.kind <> 'update_request')))));
CREATE INDEX ON seed_existing (norm);
CREATE INDEX ON seed_existing (reg) WHERE reg <> '';

-- 5a. Re-run: this research id was already imported (any classification, archived included)
UPDATE seed_mfr_stage s
   SET skip_reason = 'already imported (same research id)', existing_org_id = o.id,
       existing_record_type = o.record_type
  FROM public.organizations o
 WHERE o.source_ref = s.source_ref;

-- 5b. (pass 1: REAL records first, so a company present as both REAL and DEMO is a plain duplicate)
-- Rule 1: same registration id (published Udyam number)
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 1: same registration id', existing_org_id = e.id, existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.registration_id IS NOT NULL AND e.reg = lower(s.registration_id) AND e.record_type = 'REAL';

-- 5c. Rule 2: same name AND same website domain
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 2: same name and website', existing_org_id = e.id, existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.website_domain IS NOT NULL
   AND e.norm = s.norm_name AND e.web = s.website_domain AND e.record_type = 'REAL';

-- 5d. Rule 3: same name AND same country AND same city
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 3: same name, country and city', existing_org_id = e.id,
       existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.country_name IS NOT NULL
   AND e.norm = s.norm_name AND e.country = lower(s.country_name) AND e.city = lower(COALESCE(s.city, '')) AND e.record_type = 'REAL';


-- 5b. (pass 2: any classification - a match found only here is a DEMO / TEST conflict, see 5f)
-- Rule 1: same registration id (published Udyam number)
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 1: same registration id', existing_org_id = e.id, existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.registration_id IS NOT NULL AND e.reg = lower(s.registration_id);

-- 5c. Rule 2: same name AND same website domain
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 2: same name and website', existing_org_id = e.id, existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.website_domain IS NOT NULL
   AND e.norm = s.norm_name AND e.web = s.website_domain;

-- 5d. Rule 3: same name AND same country AND same city
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 3: same name, country and city', existing_org_id = e.id,
       existing_record_type = e.record_type
  FROM seed_existing e
 WHERE s.skip_reason IS NULL AND s.country_name IS NOT NULL
   AND e.norm = s.norm_name AND e.country = lower(s.country_name) AND e.city = lower(COALESCE(s.city, ''));

-- 5e. A bare name match with nothing else to compare: never guess
UPDATE seed_mfr_stage s
   SET skip_reason = 'ambiguous: name exists, no country / city / website / registration id to compare'
 WHERE s.skip_reason IS NULL AND s.country_name IS NULL AND s.city IS NULL AND s.website_domain IS NULL
   AND s.registration_id IS NULL AND EXISTS (SELECT 1 FROM seed_existing e WHERE e.norm = s.norm_name);

-- 5f. Demo protection: a match with a DEMO / TEST record is a CONFLICT for an admin, not a duplicate
UPDATE seed_mfr_stage
   SET skip_reason = 'CONFLICT with existing ' || existing_record_type || ' record (' || skip_reason
                     || ') - not imported, existing record unchanged'
 WHERE skip_reason IS NOT NULL AND existing_record_type IS NOT NULL AND existing_record_type <> 'REAL'
   AND skip_reason NOT LIKE 'already imported%';

-- 5g. Same rules between rows of THIS file (the CSV importer also compares each row with the earlier
--     rows of its file): the first research id (in id order) is kept, later matches are skipped.
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 1: same registration id as research row ' || d.first_id || ' in this file'
  FROM (SELECT company_id, first_value(company_id) OVER w AS first_id, row_number() OVER w AS rn
          FROM seed_mfr_stage WHERE skip_reason IS NULL AND registration_id IS NOT NULL
        WINDOW w AS (PARTITION BY lower(registration_id) ORDER BY company_id)) d
 WHERE d.company_id = s.company_id AND d.rn > 1;
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 2: same name and website as research row ' || d.first_id || ' in this file'
  FROM (SELECT company_id, first_value(company_id) OVER w AS first_id, row_number() OVER w AS rn
          FROM seed_mfr_stage WHERE skip_reason IS NULL AND website_domain IS NOT NULL
        WINDOW w AS (PARTITION BY norm_name, website_domain ORDER BY company_id)) d
 WHERE d.company_id = s.company_id AND d.rn > 1;
UPDATE seed_mfr_stage s
   SET skip_reason = 'rule 3: same name, country and city as research row ' || d.first_id || ' in this file'
  FROM (SELECT company_id, first_value(company_id) OVER w AS first_id, row_number() OVER w AS rn
          FROM seed_mfr_stage WHERE skip_reason IS NULL AND country_name IS NOT NULL
        WINDOW w AS (PARTITION BY norm_name, lower(country_name), lower(COALESCE(city, '')) ORDER BY company_id)) d
 WHERE d.company_id = s.company_id AND d.rn > 1;

-- ---------------------------------------------------------------------------
-- 6. INSERTS (FK order: import_batches → organizations → organization_profiles → facilities →
--    onboarding history → admin_internal_notes)
-- ---------------------------------------------------------------------------
-- 6a. The import batch (same content = same batch on re-runs)
CREATE TEMP TABLE seed_batch ON COMMIT DROP AS
WITH b AS (
  INSERT INTO public.import_batches (source_reference, content_sha256, imported_by, row_count)
  VALUES ('seed_tamil_nadu.sql', '6fe5c1721d07f2dd2d4daf49536b02dbca9ac01832b762eae2f6f402888f5067', 'research_seed:' || current_user, 3220)
  ON CONFLICT (content_sha256) DO UPDATE SET last_run_at = now()
  RETURNING id)
SELECT id FROM b;

-- 6b. organizations — REAL data, explicitly
INSERT INTO public.organizations
       (id, display_name, organization_type, industry_id, description, website_domain, primary_geography,
        status, verification_status, source_ref, record_type, entry_source, onboarding_source, import_batch_id)
SELECT  s.new_org_id, s.display_name, 'manufacturer', s.industry_id, s.description, s.website_domain,
        s.primary_geography, 'claim_pending', 'unverified', s.source_ref, 'REAL', 'IMPORTED',
        'database_import', b.id
  FROM seed_mfr_stage s CROSS JOIN seed_batch b
 WHERE s.skip_reason IS NULL
 ORDER BY s.company_id;

-- 6c. organization_profiles (1:1)
INSERT INTO public.organization_profiles
       (organization_id, registration_id, contact_email, contact_phone, address_line1,
        country_code, region_code, postal_code, company_category, country_name)
SELECT  new_org_id, registration_id, contact_email, contact_phone, address_line1,
        country_code, region_code, postal_code, company_category, country_name
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
 ORDER BY company_id
ON CONFLICT (organization_id) DO NOTHING;

-- 6d. facilities — one headquarters row per company with a published location (draft + private, so
--     nothing becomes visible). facility_type 'factory' only where the source calls the address a
--     factory / facility; otherwise it is the listed (often registered-office) address.
INSERT INTO public.facilities
       (organization_id, name, facility_type, is_headquarters, address, address_line1, city, state_province,
        postal_code, country_code, region_code, country_name, visibility, status)
SELECT  new_org_id, display_name || ' Headquarters', CASE WHEN is_factory THEN 'factory' END, true,
        address_line1, address_line1, city, state_name, postal_code, country_code, region_code, country_name,
        'private', 'draft'
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
   AND (address_line1 IS NOT NULL OR city IS NOT NULL OR state_name IS NOT NULL OR country_name IS NOT NULL)
 ORDER BY company_id;

-- 6e. onboarding history: one 'imported' event per company (same as the CSV importer)
INSERT INTO public.manufacturer_submission_events
       (organization_id, event, actor_role, source, import_batch_id, idempotency_key, details)
SELECT  s.new_org_id, 'imported', 'system', 'database_import', b.id, 'imported:' || s.new_org_id,
        jsonb_build_object('reference', 'seed_tamil_nadu.sql', 'research_id', s.company_id, 'record_type', 'REAL')
  FROM seed_mfr_stage s CROSS JOIN seed_batch b
 WHERE s.skip_reason IS NULL
ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

-- 6f. admin_internal_notes — research provenance, caveats and published facts that have no
--     dedicated column (contact person, all phones/emails, evidence URLs, review flags …).
INSERT INTO public.admin_internal_notes (manufacturer_id, admin_id, note, shared_with_manufacturer)
SELECT  new_org_id, NULL, internal_note, false
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
 ORDER BY company_id;

-- ---------------------------------------------------------------------------
-- 7. IN-TRANSACTION ASSERTIONS — any failure rolls back the whole import
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_expected int; v_orgs int; v_profiles int; v_notes int; v_fac_expected int; v_fac int; v_events int;
  v_bad int; v_dupe int; v_members int; v_staged int; v_changed int;
BEGIN
  SELECT count(*) INTO v_staged FROM seed_mfr_stage;
  IF v_staged <> 3220 THEN
    RAISE EXCEPTION 'staged % rows, expected 3220', v_staged;
  END IF;

  SELECT count(*) FILTER (WHERE skip_reason IS NULL),
         count(*) FILTER (WHERE skip_reason IS NULL AND (address_line1 IS NOT NULL OR city IS NOT NULL
                                                        OR state_name IS NOT NULL OR country_name IS NOT NULL))
    INTO v_expected, v_fac_expected FROM seed_mfr_stage;

  SELECT count(*) INTO v_orgs     FROM public.organizations o        JOIN seed_mfr_stage s ON s.new_org_id = o.id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_profiles FROM public.organization_profiles p JOIN seed_mfr_stage s ON s.new_org_id = p.organization_id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_fac      FROM public.facilities f           JOIN seed_mfr_stage s ON s.new_org_id = f.organization_id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_notes    FROM public.admin_internal_notes n JOIN seed_mfr_stage s ON s.new_org_id = n.manufacturer_id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_events   FROM public.manufacturer_submission_events e JOIN seed_mfr_stage s
                                    ON s.new_org_id = e.organization_id AND s.skip_reason IS NULL AND e.event = 'imported';

  IF v_orgs <> v_expected OR v_profiles <> v_expected OR v_notes <> v_expected OR v_events <> v_expected
     OR v_fac <> v_fac_expected THEN
    RAISE EXCEPTION 'row-count mismatch: expected % orgs/profiles/notes/events and % facilities; got orgs=% profiles=% notes=% events=% facilities=%',
      v_expected, v_fac_expected, v_orgs, v_profiles, v_notes, v_events, v_fac;
  END IF;

  -- imported orgs must be REAL data, unowned, unapproved, unverified
  SELECT count(*) INTO v_bad
    FROM public.organizations o JOIN seed_mfr_stage s ON s.new_org_id = o.id AND s.skip_reason IS NULL
   WHERE o.record_type <> 'REAL' OR o.status <> 'claim_pending' OR o.verification_status <> 'unverified'
      OR o.created_by_user_id IS NOT NULL OR o.assigned_admin_user_id IS NOT NULL
      OR o.clerk_organization_id IS NOT NULL OR o.entry_source <> 'IMPORTED'
      OR o.onboarding_source <> 'database_import' OR o.import_batch_id IS NULL
      OR o.organization_type <> 'manufacturer' OR o.is_archived;
  IF v_bad > 0 THEN RAISE EXCEPTION '% imported organizations have unexpected classification/ownership/approval state', v_bad; END IF;

  SELECT count(*) INTO v_members
    FROM public.memberships m JOIN seed_mfr_stage s ON s.new_org_id = m.organization_id AND s.skip_reason IS NULL;
  IF v_members > 0 THEN RAISE EXCEPTION '% memberships reference newly imported organizations', v_members; END IF;

  -- existing records matched as duplicates / conflicts were not changed (DEMO stays DEMO)
  SELECT count(*) INTO v_changed
    FROM seed_mfr_stage s JOIN public.organizations o ON o.id = s.existing_org_id
   WHERE s.existing_record_type IS NOT NULL AND o.record_type <> s.existing_record_type;
  IF v_changed > 0 THEN RAISE EXCEPTION '% existing records changed classification during the import', v_changed; END IF;

  SELECT count(*) INTO v_dupe FROM (
    SELECT o.source_ref FROM public.organizations o
     WHERE o.source_ref IN (SELECT source_ref FROM seed_mfr_stage WHERE skip_reason IS NULL)
     GROUP BY o.source_ref HAVING count(*) > 1) d;
  IF v_dupe > 0 THEN RAISE EXCEPTION '% duplicate source_ref values would be created', v_dupe; END IF;

  RAISE NOTICE 'seed OK: % organizations (REAL), % profiles, % facilities, % internal notes inserted; % skipped (% demo conflicts)',
    v_orgs, v_profiles, v_fac, v_notes, v_staged - v_expected,
    (SELECT count(*) FROM seed_mfr_stage WHERE skip_reason LIKE 'CONFLICT%');
END $$;

-- ---------------------------------------------------------------------------
-- 8. RUN SUMMARY (printed before commit)
-- ---------------------------------------------------------------------------
SELECT coalesce(skip_reason, 'inserted (REAL)') AS outcome, count(*) AS records
  FROM seed_mfr_stage GROUP BY 1 ORDER BY 2 DESC;

SELECT count(*) FILTER (WHERE skip_reason IS NULL)                              AS inserted,
       count(*) FILTER (WHERE skip_reason IS NULL AND industry_id IS NULL)      AS inserted_without_industry_match,
       count(*) FILTER (WHERE skip_reason IS NULL AND state_name IS NOT NULL AND region_code IS NULL) AS inserted_state_without_region_match,
       count(*) FILTER (WHERE skip_reason LIKE 'CONFLICT%')                     AS demo_conflicts_to_resolve
  FROM seed_mfr_stage;

-- DEMO / TEST conflicts first, then other matches with pre-existing companies (first 500; on a
-- re-run every record shows as 'already imported' and is omitted here)
SELECT company_id, display_name, existing_record_type, skip_reason, existing_org_id
  FROM seed_mfr_stage
 WHERE skip_reason IS NOT NULL AND skip_reason NOT LIKE 'already imported%'
 ORDER BY (skip_reason LIKE 'CONFLICT%') DESC, skip_reason, company_id
 LIMIT 500;

COMMIT;

-- =============================================================================
-- 9. POST-COMMIT VALIDATION QUERIES (read-only; safe to run any time)
-- =============================================================================

-- 9.1 Imported research rows by classification and state (all must be REAL)
SELECT o.record_type, o.status, o.verification_status, o.onboarding_source, count(*) AS orgs
  FROM public.organizations o
 WHERE o.source_ref LIKE 'india_mfr_research:%'
 GROUP BY 1, 2, 3, 4 ORDER BY 5 DESC;

-- 9.2 Duplicate check: any research ID imported more than once (expected: 0 rows)
SELECT source_ref, count(*) FROM public.organizations
 WHERE source_ref LIKE 'india_mfr_research:%'
 GROUP BY source_ref HAVING count(*) > 1;

-- 9.3 Imported rows that look like the same company as another record under the project's rules
--     (same name + country + city, or same name + website) - expected: 0 rows
SELECT i.id AS imported_org_id, i.display_name, e.id AS other_org_id, e.display_name AS other_name, e.record_type
  FROM public.organizations i
  JOIN public.organizations e
    ON e.id <> i.id AND e.organization_type = 'manufacturer' AND NOT e.is_archived AND e.record_type <> 'TEST'
   AND lower(regexp_replace(btrim(e.display_name), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(i.display_name), '\s+', ' ', 'g'))
   AND (e.source_ref IS NULL OR e.source_ref NOT LIKE 'india_mfr_research:%')
  LEFT JOIN public.facilities fi ON fi.organization_id = i.id AND fi.is_headquarters
  LEFT JOIN public.facilities fe ON fe.organization_id = e.id AND fe.is_headquarters
 WHERE i.source_ref LIKE 'india_mfr_research:%' AND i.created_at > e.created_at
   AND ((lower(fi.city) = lower(fe.city) AND lower(fi.country_name) = lower(fe.country_name))
        OR (i.website_domain IS NOT NULL AND lower(i.website_domain) = lower(e.website_domain)));

-- 9.4 Relationship integrity (expected: every count = 0)
SELECT
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%'
      AND NOT EXISTS (SELECT 1 FROM public.organization_profiles p WHERE p.organization_id = o.id))   AS orgs_without_profile,
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%'
      AND NOT EXISTS (SELECT 1 FROM public.admin_internal_notes n WHERE n.manufacturer_id = o.id))    AS orgs_without_note,
  (SELECT count(*) FROM public.organization_profiles p JOIN public.organizations o ON o.id = p.organization_id
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND p.country_code IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.countries c WHERE c.code = p.country_code))                 AS profiles_bad_country,
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND o.industry_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.taxonomy_terms t WHERE t.id = o.industry_id AND t.term_type = 'industry')) AS orgs_bad_industry,
  (SELECT count(*) FROM public.facilities f JOIN public.organizations o ON o.id = f.organization_id
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND o.import_batch_id IS NOT NULL
      AND (f.visibility <> 'private' OR f.status <> 'draft') AND o.status = 'claim_pending')         AS unclaimed_facilities_not_private_draft;

-- 9.5 Classification / ownership / approval of imported orgs (right after import: only imported_total
--     and imported_real > 0; companies claimed or approved later through the app change these over time)
SELECT count(*)                                                            AS imported_total,
       count(*) FILTER (WHERE o.record_type = 'REAL')                      AS imported_real,
       count(*) FILTER (WHERE o.record_type <> 'REAL')                     AS reclassified_by_admin,
       count(*) FILTER (WHERE o.created_by_user_id IS NOT NULL)            AS with_creator,
       count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.memberships m WHERE m.organization_id = o.id)) AS with_members,
       count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.manufacturer_onboarding mo
                                       WHERE mo.organization_id = o.id AND mo.status = 'approved')) AS onboarding_approved
  FROM public.organizations o
 WHERE o.source_ref LIKE 'india_mfr_research:%';

-- 9.6 Open demo conflicts from this or earlier runs are listed in section 8 of each run's output.
--     Spot-check a few imported records against the source workbook:
SELECT o.source_ref, o.display_name, o.record_type, o.primary_geography, o.website_domain,
       p.contact_email, p.contact_phone, p.postal_code, p.registration_id, p.company_category
  FROM public.organizations o JOIN public.organization_profiles p ON p.organization_id = o.id
 WHERE o.source_ref IN ('india_mfr_research:TN-002D3A18AB', 'india_mfr_research:TN-002FE509A3', 'india_mfr_research:TN-00529280CC');
